@section('subtitle', 'Build server-calculated drafts and freeze historical employee and money snapshots.')
@section('actions')<button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#payroll-modal">New payroll draft</button>@endsection
@section('content')
<div class="alert alert-warning">Statutory rates and entitlement defaults are not enabled until Finance approves them. Authorized payroll staff enter reviewed components; the server derives and locks totals.</div>
<x-hris.table id="payroll-table" endpoint="/hr/payroll/data" search filters :columns="[['key'=>'payroll_number','label'=>'Payroll no.'],['key'=>'type','label'=>'Type'],['key'=>'period_start','label'=>'From'],['key'=>'period_end','label'=>'Through'],['key'=>'status','label'=>'Status'],['key'=>'lines_count','label'=>'Employees']]" :actions="[['name'=>'edit','label'=>'Open']]"/>
<x-hris.modal id="payroll-modal" title="Create payroll draft"><form id="payroll-form" data-endpoint="/hr/payroll"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none" tabindex="-1"></div><div class="row g-3"><x-hris.field name="type" type="select" :options="['Regular'=>'Regular','CSW'=>'CSW / Probationary','Mid-year Bonus'=>'Mid-year Bonus','Year-end Bonus'=>'Year-end Bonus']" required/><x-hris.field name="payroll_number" required/><x-hris.field name="fund_cluster" required/><x-hris.field name="period_start" type="date" required/><x-hris.field name="period_end" type="date" required/></div></div><div class="modal-footer"><button class="btn btn-primary">Create draft</button></div></form></x-hris.modal>
<x-hris.modal id="payroll-lines-modal" title="Payroll employees"><div class="modal-body"><div class="d-flex flex-wrap gap-2 mb-3"><button id="add-line" class="btn btn-primary">Add or recalculate employee</button><button id="finalize-payroll" class="btn btn-outline-danger">Finalize and lock</button><a id="export-payroll" class="btn btn-outline-secondary d-none">Export CSV</a></div><x-hris.table id="payroll-lines" endpoint="/hr/payroll/0/lines" search :columns="[['key'=>'employee_snapshot.name','label'=>'Employee'],['key'=>'basic_salary','label'=>'Basic'],['key'=>'gross','label'=>'Gross'],['key'=>'total_deductions','label'=>'Deductions'],['key'=>'net','label'=>'Net']]" :actions="[['name'=>'details','label'=>'Details'],['name'=>'delete','label'=>'Remove','danger'=>true]]"/></div></x-hris.modal>
<x-hris.modal id="line-modal" title="Payroll employee"><form id="line-form"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none" tabindex="-1"></div><div class="row g-3"><div class="col-12"><x-hris.employee-picker name="user_id" label="Employee"/></div>@foreach(['pera'=>'PERA','rata'=>'RATA','other_compensation'=>'Other compensation','statutory_deductions'=>'Statutory deductions','other_deductions'=>'Other deductions','late_minutes'=>'Late minutes','undertime_minutes'=>'Undertime minutes','absence_days'=>'Absence days'] as $name=>$label)<x-hris.field :name="$name" :label="$label" type="number" min="0" :step="$name==='absence_days'?'0.001':'0.01'" value="0"/>@endforeach</div></div><div class="modal-footer"><button class="btn btn-primary">Calculate and save</button></div></form></x-hris.modal>
@endsection
@push('scripts')<script>document.addEventListener('hris:ready',()=>{const master=document.querySelector('#payroll-table'),lines=document.querySelector('#payroll-lines'),header=document.querySelector('#payroll-form'),line=document.querySelector('#line-form');let current=null;HRIS.bindForm(header,{success:()=>master.table.load()});HRIS.bindForm(line,{success:()=>lines.table.load()});master.addEventListener('table:action',({detail:{row}})=>{current=row;lines.dataset.endpoint=`/hr/payroll/${row.id}/lines`;lines.table.page=1;lines.table.load();document.querySelector('#finalize-payroll').disabled=row.status!=='Draft';const exp=document.querySelector('#export-payroll');exp.href=`/hr/payroll/${row.id}/export`;exp.classList.toggle('d-none',row.status!=='Finalized');HRIS.openModal('payroll-lines-modal')});document.querySelector('#add-line').onclick=()=>{if(current.status!=='Draft')return;HRIS.fillForm(line,{pera:0,rata:0,other_compensation:0,statutory_deductions:0,other_deductions:0,late_minutes:0,undertime_minutes:0,absence_days:0});line.dataset.endpoint=`/hr/payroll/${current.id}/lines`;HRIS.openModal('line-modal')};document.querySelector('#finalize-payroll').onclick=async()=>{if(!await HRIS.confirm('Finalize this payroll? Amounts and employee snapshots will be locked.'))return;try{HRIS.feedback((await HRIS.request(`/hr/payroll/${current.id}/finalize`,{method:'POST'})).message);master.table.load();document.querySelector('#finalize-payroll').disabled=true}catch(e){HRIS.feedback(e.message,true)}};lines.addEventListener('table:action',async({detail:{action,row}})=>{if(action==='details')HRIS.showDetails('Payroll line',row);else if(await HRIS.confirm('Remove this draft line?')){try{HRIS.feedback((await HRIS.request(`/hr/payroll/${current.id}/lines/${row.id}`,{method:'DELETE'})).message);lines.table.load()}catch(e){HRIS.feedback(e.message,true)}}})});</script>@endpush
